     it('US-03-AC-16 the keyboard order is "Editar mis datos", "Cambiar plan", the terms region, "Acepto los términos y condiciones", the simulation group, "Pagar"', async () => {
       await openCo();
-      expect(tabStops(app.root)).toEqual(['Editar mis datos', 'Cambiar plan', 'terms region', 'checkbox', 'simulation group', 'Pagar']);
+      // US-04-AC-28: two links now lead the page, the country chip and the back link
+      expect(tabStops(app.root)).toEqual(['Cambiar país (actual: Colombia)', 'Volver a planes', 'Editar mis datos', 'Cambiar plan', 'terms region', 'checkbox', 'simulation group', 'Pagar']);
     });

     it('US-03-AC-17 "Tus datos", "Tu vehículo", "Plan elegido" and "Términos y condiciones" are headings of level 2, and the title of the page is the only level 1', async () => {
diff --git a/frontend/src/testing/summary-dom.ts b/frontend/src/testing/summary-dom.ts
index 85c2047..ffa3b7d 100644
--- a/frontend/src/testing/summary-dom.ts
+++ b/frontend/src/testing/summary-dom.ts
@@ -102,6 +102,7 @@ export function tabStops(root: ParentNode): string[] {
     else if (el instanceof HTMLInputElement && el.type === 'checkbox') name = 'checkbox';
     else if (el.getAttribute('role') === 'region') name = 'terms region';
     else if (el.tagName === 'BUTTON') name = normalise(el.textContent);
+    else if (el.tagName === 'A') name = normalise(el.getAttribute('aria-label') ?? el.textContent); // a link is named, never collapsed to 'a' (US-04-AC-28)
     else name = el.tagName.toLowerCase();
     if (stops[stops.length - 1] !== name) stops.push(name);
   }

