const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage();
  await p.setContent('<input id=i>');
  await p.evaluate(() => {
    const el = document.getElementById('i');
    window.log = [];
    for (const t of ['compositionstart','compositionupdate','compositionend']) el.addEventListener(t, e => log.push(t+':'+e.data));
    el.addEventListener('input', (e) => {
      const raw = el.value; const kept = [...raw].filter(c => /^\p{L}$/u.test(c) || \" '-.\".includes(c)).join('');
      log.push('input '+e.inputType+' composing='+e.isComposing+' raw='+JSON.stringify(raw));
      if (kept !== raw) { el.value = kept; el.setSelectionRange(kept.length, kept.length); }
    }, { capture: true });
    el.focus();
  });
  const s = await p.context().newCDPSession(p);
  await p.keyboard.type('Jos');
  await s.send('Input.imeSetComposition', { text: '´', selectionStart: 1, selectionEnd: 1 });
  await s.send('Input.imeSetComposition', { text: 'é', selectionStart: 1, selectionEnd: 1 });
  await s.send('Input.insertText', { text: 'é' });
  console.log(await p.evaluate(() => ({ v: document.getElementById('i').value, log })));
  // Android-like: compose lowercase word in an uppercase field
  await p.setContent('<input id=j>');
  await p.evaluate(() => { const el = document.getElementById('j'); el.addEventListener('input', () => { const u = el.value.toUpperCase(); if (u !== el.value) { el.value = u; el.setSelectionRange(u.length,u.length);} }, {capture:true}); el.focus(); });
  for (const t of ['a','ab','abc']) await s.send('Input.imeSetComposition', { text: t, selectionStart: t.length, selectionEnd: t.length });
  await s.send('Input.insertText', { text: 'abc' });
  console.log(await p.evaluate(() => document.getElementById('j').value));
  await b.close();
})().catch(e => { console.error(e); process.exit(1); });
