:host {
  /* The sticky header sticks within the page, not within this host. */
  display: contents;
}
.header {
  position: sticky;
  top: 0;
  z-index: var(--z-header);
  border-bottom: var(--border-width-hairline) solid var(--color-border-subtle);
  background: var(--color-surface-raised);
}
.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  min-height: var(--size-header-height);
  max-width: var(--size-content-max);
  margin: 0 auto;
  padding: var(--space-3) var(--space-4);
}
.header__product {
  min-width: 0;
  font-family: var(--font-display);
  font-size: var(--text-small);
  font-weight: var(--weight-bold);
  font-stretch: var(--text-subheading-stretch);
  line-height: var(--leading-small);
}
.chip {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--space-2);
  min-height: var(--size-target-min);
  padding: var(--space-1) var(--space-3);
  border-bottom: var(--border-width-selected) solid var(--color-country-accent);
  border-radius: var(--radius-control);
  color: var(--color-text);
  font-size: var(--text-small);
  font-weight: var(--weight-semibold);
  line-height: var(--leading-small);
  text-decoration: none;
}
@media (hover: hover) {
  .chip:hover {
    background: var(--color-surface-hover);
  }
}
@media (min-width: 37.5em) {
  .header__inner {
    padding-inline: var(--space-5);
  }
}
:host {
  display: inline-flex;
  flex: none;
  align-items: center;
}
